import java.util.*;
import java.io.*;

public class Main {
    static long[] mstWeights(int n, long[][] edges) {
        // Write your solution here
        return new long[]{0, 0};
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        long[][] edges = new long[m][3];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < 3; j++) { in.nextToken(); edges[i][j] = (long) in.nval; }
        }
        long[] res = mstWeights(n, edges);
        System.out.println(res[0] + " " + res[1]);
    }
}
